59009  static int js_atomics_get_ptr(JSContext *ctx, void **pptr,
 59010                                JSObject **pobj, uint64_t *pidx,
 59011                                int *psize_log2, JSClassID *pclass_id,
 59012                                JSValueConst obj, JSValueConst idx_val,
 59013                                int is_waitable)
 59014  {
 59015      JSObject *p;
 59016      JSTypedArray *ta;
 59017      JSArrayBuffer *abuf;
 59018      void *ptr;
 59019      uint64_t idx;
 59020      BOOL err;
 59021      int size_log2, old_len;
 59022
 59023      if (JS_VALUE_GET_TAG(obj) != JS_TAG_OBJECT)
 59024          goto fail;
 59025      p = JS_VALUE_GET_OBJ(obj);
 59026      if (is_waitable)
 59027          err = (p->class_id != JS_CLASS_INT32_ARRAY &&
 59028                 p->class_id != JS_CLASS_BIG_INT64_ARRAY);
 59029      else
 59030          err = !(p->class_id >= JS_CLASS_INT8_ARRAY &&
 59031                  p->class_id <= JS_CLASS_BIG_UINT64_ARRAY);
 59032      if (err) {
 59033      fail:
 59034          JS_ThrowTypeError(ctx, "integer TypedArray expected");
 59035          return -1;
 59036      }
 59037      ta = p->u.typed_array;
 59038      abuf = ta->buffer->u.array_buffer;
 59039      if (!abuf->shared) {
 59040          if (is_waitable == 2) {
 59041              JS_ThrowTypeError(ctx, "not a SharedArrayBuffer TypedArray");
 59042              return -1;
 59043          }
 59044          if (abuf->detached) {
 59045              JS_ThrowTypeErrorDetachedArrayBuffer(ctx);
 59046              return -1;
 59047          }
 59048      }
 59049      old_len = p->u.array.count;
 59050
 59051      if (JS_ToIndex(ctx, &idx, idx_val)) {
 59052          return -1;
 59053      }
 59054
 59055      if (idx >= old_len)
 59056          goto oob;
 59057
 59058      if (is_waitable == 1) {
 59059          /* notify(): just avoid having an invalid pointer if overflow */
 59060          if (idx >= p->u.array.count)
 59061              ptr = NULL;
 59062      } else {
 59063          /* RevalidateAtomicAccess() */
 59064          if (typed_array_is_oob(p)) {
 59065              JS_ThrowTypeErrorArrayBufferOOB(ctx);
 59066              return -1;
 59067          }
 59068          if (idx >= p->u.array.count) {
 59069          oob:
 59070              JS_ThrowRangeError(ctx, "out-of-bound access");
 59071              return -1;
 59072          }
 59073      }
 59074
 59075      size_log2 = typed_array_size_log2(p->class_id);
 59076      ptr = p->u.array.u.uint8_ptr + ((uintptr_t)idx << size_log2);
 59077
 59078      *pptr = ptr;
 59079      if (pobj)
 59080          *pobj = p;
 59081      if (pidx)
 59082          *pidx = idx;
 59083      if (psize_log2)
 59084          *psize_log2 = size_log2;
 59085      if (pclass_id)
 59086          *pclass_id = p->class_id;
 59087      return 0;
 59088  }
